from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int]) -> int:
    """Return the sum of square(x) for every x in xs.

    The squares are computed concurrently on a ThreadPoolExecutor. Results
    are combined as exact integers, so the total is identical regardless of
    how many workers run or in what order the squares complete.
    """
    with ThreadPoolExecutor() as pool:
        return sum(pool.map(square, xs))


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single() -> None:
    assert sum_squares([7]) == 49


def test_sum_squares_small() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_negatives() -> None:
    assert sum_squares([-3, 3, -4]) == 34


def test_sum_squares_matches_sequential() -> None:
    xs = list(range(-500, 501))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs) == expected


def test_sum_squares_large_values() -> None:
    xs = [10**9, -(10**9)]
    assert sum_squares(xs) == 2 * 10**18


@pytest.mark.parametrize("n", [1, 2, 8, 64])
def test_sum_squares_length_param(n: int) -> None:
    xs = list(range(n))
    assert sum_squares(xs) == sum(x * x for x in xs)


def test_sum_squares_uses_thread_pool_result_type() -> None:
    result = sum_squares([2, 4])
    assert isinstance(result, int)
    assert ThreadPoolExecutor is not None
